<template><ForgeDialog title="Site sucker" description="Mirror a site with explicit page, timeout and media limits." eyebrow="WORKSPACE / NETWORK" wide @close="emit('close')"><div class="form"><label>Start URL<input v-model="controller.url" placeholder="https://example.com" /></label><div class="grid"><label>Output folder<input v-model="controller.config.dir" /></label><label>Proxy<input v-model="controller.config.proxy" placeholder="Optional" /></label><label>Page limit<input v-model.number="controller.config.pageLimit" type="number" min="1" max="10000" /></label><label>Timeout (seconds)<input v-model.number="controller.config.timeout" type="number" min="1" max="600" /></label><label>Max image (MB)<input v-model.number="controller.config.maxImgSize" type="number" min="1" max="2048" /></label><label>Max video (MB)<input v-model.number="controller.config.maxVideoSize" type="number" min="1" max="4096" /></label></div><div class="actions"><button class="primary-button" :disabled="controller.running" @click="controller.run()">{{ controller.running ? 'Mirroring…' : 'Start mirror' }}</button><button class="action-button" :disabled="!controller.running" @click="controller.cancel()">Cancel</button></div><p class="status">{{ controller.status }} · {{ controller.links.length }} links</p><p v-if="controller.error" class="forge-alert forge-alert--error">{{ controller.error }}</p><div class="links"><article v-for="link in controller.links" :key="link.url"><code>{{ link.url }}</code><em>{{ link.state }}</em></article><p v-if="!controller.links.length" class="empty-copy">Link progress appears here.</p></div></div><template #footer><span class="website-help">Limits are clamped before dispatch. Cancellation destroys the native Site Sucker workers and clears task state.</span></template></ForgeDialog></template>
<script setup lang="ts">
import { onMounted } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { siteSuckerController as controller } from '../state/siteSuckerController'
const emit = defineEmits(['close'])
onMounted(() => controller.init())
</script>
<style scoped>.form{display:grid;gap:14px}.form label{display:grid;gap:6px;color:var(--pqt-text-muted);font-size:11px}.form input{padding:9px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border);border-radius:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.actions{display:flex;gap:8px}.status{color:var(--pqt-accent)}.links{display:grid;gap:5px;max-height:250px;overflow:auto}.links article{display:flex;justify-content:space-between;padding:8px;border:1px solid var(--pqt-border);border-radius:6px}.links code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.links em{color:var(--pqt-accent);font-style:normal}</style>
